```section
<style id="j2-base-style">
:root{
  --j2-on-primary:#FFFFFF;
  --j2-on-accent:#0B1220;
  --j2-border:#D5DCE6;
  --j2-field-border:#5B6577;
}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:80px;-webkit-text-size-adjust:100%;overflow-x:clip}
body{
  margin:0;max-width:100%;overflow-x:clip;
  font-family:var(--j2-font-body,system-ui,-apple-system,'Segoe UI',Arial,sans-serif);
  font-size:1rem;line-height:1.6;
  background:var(--j2-background,#F5F7FA);color:var(--j2-text,#0B1220);
}
img,svg,video,canvas,iframe,picture{max-width:100%;height:auto}
p,li,dd,dt,td,th,a,span,label,summary,h1,h2,h3,h4{overflow-wrap:anywhere}
section{padding-block:clamp(40px,8vw,64px);padding-inline:16px;max-width:100%}
section>*{max-width:1120px;margin-inline:auto}
h1,h2,h3,h4{
  font-family:var(--j2-font-heading,'Arial Narrow',Impact,sans-serif);
  font-weight:800;line-height:1.1;text-transform:uppercase;letter-spacing:.01em;
  color:var(--j2-text,#0B1220);margin:0 0 .5em;
}
h1{font-size:clamp(2.25rem,9vw,4.25rem)}
h2{font-size:clamp(1.75rem,6vw,2.75rem)}
h3{font-size:clamp(1.25rem,4vw,1.5rem)}
h2::after{content:"";display:block;width:56px;height:6px;margin-top:8px;background:var(--j2-accent,#F25C05);border-radius:3px}
p{margin:0 0 1em}
a{color:var(--j2-primary,#0A3D8F);text-underline-offset:3px}
:focus-visible{outline:3px solid var(--j2-accent,#F25C05);outline-offset:2px}

/* Buttons */
.j2-btn{
  display:inline-flex;align-items:center;justify-content:center;gap:8px;
  min-height:44px;min-width:44px;padding:12px 24px;max-width:100%;
  font-family:inherit;font-size:1rem;font-weight:700;line-height:1.2;text-align:center;
  text-transform:uppercase;letter-spacing:.04em;text-decoration:none;cursor:pointer;
  border:2px solid var(--j2-primary,#0A3D8F);border-radius:var(--j2-radius,12px);
  background:var(--j2-primary,#0A3D8F);color:var(--j2-on-primary,#FFFFFF);
}
.j2-btn-primary{background:var(--j2-accent,#F25C05);border-color:var(--j2-accent,#F25C05);color:var(--j2-on-accent,#0B1220)}
.j2-btn-secondary{background:transparent;border-color:var(--j2-primary,#0A3D8F);color:var(--j2-primary,#0A3D8F)}
.j2-btn:hover{filter:brightness(1.08)}
.j2-btn:active{transform:translateY(1px)}
.j2-btn[disabled]{opacity:.6;cursor:not-allowed}

/* Cards and grids */
.j2-card{
  background:var(--j2-surface,#FFFFFF);color:var(--j2-text,#0B1220);
  border:1px solid var(--j2-border,#D5DCE6);border-top:4px solid var(--j2-accent,#F25C05);
  border-radius:var(--j2-radius,12px);padding:24px;min-width:0;
  box-shadow:0 2px 8px rgba(11,31,58,.08);
}
.j2-grid{display:grid;gap:24px;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr))}
.j2-grid>*{min-width:0}

/* Forms */
form{max-width:100%}
fieldset{border:0;margin:0;padding:0;min-width:0}
label{display:block;font-weight:600;margin-bottom:4px}
label:has(input[type=radio]),label:has(input[type=checkbox]){display:inline-flex;align-items:center;gap:8px;min-height:44px;margin-right:16px}
input,select,textarea{
  display:block;width:100%;max-width:100%;min-height:44px;padding:10px 12px;margin-bottom:16px;
  font:inherit;color:var(--j2-text,#0B1220);background:var(--j2-surface,#FFFFFF);
  border:2px solid var(--j2-field-border,#5B6577);border-radius:8px;
}
input[type=radio],input[type=checkbox]{display:inline-block;width:24px;height:24px;min-height:0;margin:0;padding:0;accent-color:var(--j2-primary,#0A3D8F)}

/* Tables, lists, details */
table{display:block;max-width:100%;overflow-x:auto;border-collapse:collapse}
th,td{padding:8px 12px;text-align:left;border-bottom:1px solid var(--j2-border,#D5DCE6)}
summary{display:flex;align-items:center;min-height:44px;cursor:pointer;font-weight:600}
.j2-nav-link{display:inline-flex;align-items:center;min-height:44px;padding:0 12px}

/* Placeholders */
.j2-route-map,.j2-logo-ph{
  display:grid;place-items:center;text-align:center;padding:16px;max-width:100%;
  border:2px dashed var(--j2-field-border,#5B6577);border-radius:var(--j2-radius,12px);
  background:var(--j2-background,#F5F7FA);color:var(--j2-muted,#4A5568);font-weight:600;
}
.j2-route-map{min-height:180px}
.j2-logo-ph{min-height:88px}

@media (max-width:480px){
  section{padding-inline:12px}
  .j2-card{padding:16px}
  .j2-btn{width:100%}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *{transition:none!important;animation:none!important}
}
</style>
```

{"say": "@Coordination Wrote #hero: h1, Pune, race day, expo day with time and venue, four .j2-cd-unit countdown units updating every second toward 14 Feb 2027 06:00 IST, and one Register now link. Note: the page-wide .j2-btn-primary count will exceed 1 once W-4 and W-5 add submit buttons.", "next": "Coordination", "reason": "The hero is written as declared, and the shared button-class collision stays flagged for Adaptation or Audit."}
```section
<section id="hero" aria-labelledby="hero-title">
<style>
#hero{background:var(--j2-secondary);color:var(--j2-surface);padding-block:clamp(48px,10vw,96px)}
#hero .j2-hero-inner{display:grid;gap:24px}
#hero h1{color:var(--j2-surface);margin:0}
#hero .j2-hero-kicker{font-family:var(--j2-font-heading);font-weight:700;font-size:clamp(1.125rem,4vw,1.5rem);text-transform:uppercase;letter-spacing:.08em;color:var(--j2-accent);margin:0}
#hero .j2-hero-facts{display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));margin:0}
#hero .j2-hero-fact{border-left:6px solid var(--j2-accent);padding-left:16px;min-width:0}
#hero .j2-hero-fact dt{font-family:var(--j2-font-heading);font-weight:700;font-size:1.125rem;text-transform:uppercase;letter-spacing:.06em;color:var(--j2-accent)}
#hero .j2-hero-fact dd{margin:4px 0 0;font-size:1.125rem;font-weight:500;color:var(--j2-surface)}
#hero #j2-countdown{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;max-width:560px;margin-inline:0}
#hero .j2-cd-unit{display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:0;padding:12px 4px;text-align:center;border:2px solid var(--j2-accent);border-radius:var(--j2-radius)}
#hero .j2-cd-num{font-family:var(--j2-font-heading);font-weight:800;font-size:clamp(1.75rem,8vw,3rem);line-height:1;color:var(--j2-surface);font-variant-numeric:tabular-nums}
#hero .j2-cd-label{margin-top:4px;font-size:.75rem;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:var(--j2-surface)}
#hero .j2-cd-note{margin:0;font-weight:600;color:var(--j2-accent)}
#hero .j2-hero-cta{margin:0}
@media (max-width:480px){#hero .j2-cd-label{font-size:.6875rem;letter-spacing:.02em}}
</style>
<div class="j2-hero-inner">
  <p class="j2-hero-kicker">Pune city running event</p>
  <h1 id="hero-title">Riverside Run 2027</h1>
  <dl class="j2-hero-facts">
    <div class="j2-hero-fact">
      <dt>Race day</dt>
      <dd>Sunday 14 February 2027</dd>
    </div>
    <div class="j2-hero-fact">
      <dt>Expo day</dt>
      <dd>Saturday 13 February 2027, 10am to 6pm</dd>
    </div>
    <div class="j2-hero-fact">
      <dt>Venue</dt>
      <dd>Riverside Grounds, 5 River Road, Pune 411001</dd>
    </div>
  </dl>
  <div id="j2-countdown" role="timer" aria-label="Time until race day, Sunday 14 February 2027">
    <div class="j2-cd-unit"><span class="j2-cd-num" data-unit="days">0</span><span class="j2-cd-label">Days</span></div>
    <div class="j2-cd-unit"><span class="j2-cd-num" data-unit="hours">00</span><span class="j2-cd-label">Hours</span></div>
    <div class="j2-cd-unit"><span class="j2-cd-num" data-unit="minutes">00</span><span class="j2-cd-label">Minutes</span></div>
    <div class="j2-cd-unit"><span class="j2-cd-num" data-unit="seconds">00</span><span class="j2-cd-label">Seconds</span></div>
  </div>
  <p class="j2-cd-note" id="j2-cd-note" hidden>Race day is here. See you at the start line.</p>
  <p class="j2-hero-cta"><a class="j2-btn j2-btn-primary" href="#register">Register now</a></p>
</div>
<script>
(function () {
  var box = document.getElementById('j2-countdown');
  if (!box) { return; }
  var target = new Date('2027-02-14T06:00:00+05:30').getTime();
  var els = {
    days: box.querySelector('[data-unit="days"]'),
    hours: box.querySelector('[data-unit="hours"]'),
    minutes: box.querySelector('[data-unit="minutes"]'),
    seconds: box.querySelector('[data-unit="seconds"]')
  };
  var note = document.getElementById('j2-cd-note');
  var timer = null;
  function pad(n) { return n < 10 ? '0' + n : String(n); }
  function set(el, text) { if (el) { el.textContent = text; } }
  function tick() {
    var diff = target - Date.now();
    if (isNaN(diff) || diff <= 0) {
      set(els.days, '0'); set(els.hours, '00'); set(els.minutes, '00'); set(els.seconds, '00');
      if (note) { note.hidden = false; }
      if (timer) { clearInterval(timer); timer = null; }
      return;
    }
    var s = Math.floor(diff / 1000);
    set(els.days, String(Math.floor(s / 86400)));
    set(els.hours, pad(Math.floor((s % 86400) / 3600)));
    set(els.minutes, pad(Math.floor((s % 3600) / 60)));
    set(els.seconds, pad(s % 60));
  }
  tick();
  timer = setInterval(tick, 1000);
})();
</script>
</section>
