  }

  /* Scroll check covers the end of the page and browsers without IntersectionObserver */
  var ticking = false;
  window.addEventListener('scroll', function () {
    if (ticking) { return; }
    ticking = true;
    window.requestAnimationFrame(function () { ticking = false; update(); });
  }, { passive: true });

  window.addEventListener('resize', function () { setNavHeight(); update(); });
  if (window.ResizeObserver) { new ResizeObserver(setNavHeight).observe(nav); }
  if (document.fonts && document.fonts.ready) { document.fonts.ready.then(function () { setNavHeight(); update(); }); }
