(function () {
  var box = document.getElementById('j2-countdown');
  if (!box) { return; }
  var target = new Date('2027-02-14T06:00:00+05:30').getTime();
  var els = {
    days: box.querySelector('[data-unit="days"]'),
    hours: box.querySelector('[data-unit="hours"]'),
    minutes: box.querySelector('[data-unit="minutes"]'),
    seconds: box.querySelector('[data-unit="seconds"]')
  };
  var note = document.getElementById('j2-cd-note');
  var timer = null;
  function pad(n) { return n < 10 ? '0' + n : String(n); }
  function set(el, text) { if (el) { el.textContent = text; } }
  function tick() {
    var diff = target - Date.now();
    if (isNaN(diff) || diff <= 0) {
      set(els.days, '--'); set(els.hours, '--'); set(els.minutes, '--'); set(els.seconds, '--');
      if (note) { note.hidden = false; }
      if (timer) { clearInterval(timer); timer = null; }
      return;
    }
    var s = Math.floor(diff / 1000);
    set(els.days, String(Math.floor(s / 86400)));
    set(els.hours, pad(Math.floor((s % 86400) / 3600)));
    set(els.minutes, pad(Math.floor((s % 3600) / 60)));
    set(els.seconds, pad(s % 60));
  }
  tick();
  timer = setInterval(tick, 1000);
})();
</script>
